class Solution {
public:
    int findMaxLength(vector<int>& nums) {
        for(auto &it : nums) it = (it == 1) ? 1 : -1;
        map<int, int> lastOccurance;

        lastOccurance[0] = -1;
        int ans = 0, sum = 0;

        for(int i=0; i<nums.size(); i++){
            sum += nums[i];
            if(lastOccurance.find(sum) != lastOccurance.end())
                ans = max(ans, i - lastOccurance[sum] );
            else
                lastOccurance[sum] = i;
        }
        return ans;
    }
};
